<template><view class="page"><view class="nav"><text @tap="uni.navigateBack()">‹</text><strong>{{driver?'司机行程订单':'我的行程订单'}}</strong></view><view v-for="item in items" :key="item.id" class="card" @tap="open(item.id)"><view class="head"><strong>{{statusText(item.status)}}</strong><text>{{formatTime(item.createdAt)}}</text></view><view class="route"><text>起 · {{item.originAddress}}</text><text>终 · {{item.destinationAddress}}</text></view><view class="foot"><text>{{item.driverEmployee?.name||'待匹配司机'}}</text><strong>¥{{Number((item.finalAmount??item.estimatedAmount)||0).toFixed(2)}}</strong></view></view><view v-if="!items.length" class="empty">暂无行程订单</view></view></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import{rideApi}from'../../../services/ride';const driver=ref(false),items=ref<any[]>([]);async function load(){const d=driver.value?await rideApi.driverOrders({page:1,pageSize:50}):await rideApi.list({page:1,pageSize:50});items.value=d?.items||[];uni.stopPullDownRefresh()}function open(id:number){uni.navigateTo({url:`/pages/ride/detail/index?id=${id}${driver.value?'&driver=1':''}`})}function formatTime(v:string){return new Date(v).toLocaleString()}function statusText(v:string){return({PREPAY_PENDING:'待预付',DISPATCHING:'等待司机接单',TO_PICKUP:'司机前往上车点',ARRIVED_PICKUP:'司机已到达',IN_TRIP:'行程中',ARRIVED_DESTINATION:'已到目的地',FARE_PENDING:'费用确认',SUPPLEMENT_PENDING:'待补款',REFUND_PENDING:'退款中',COMPLETED:'已完成',CANCELLED:'已取消',NO_DRIVER:'暂无司机'}as any)[v]||v}onLoad((q:any)=>driver.value=q?.driver==='1');onMounted(load);onPullDownRefresh(load)</script>
<style scoped>.page{min-height:100vh;background:#f1f5f9;padding:24rpx;box-sizing:border-box}.nav{display:flex;align-items:center;gap:20rpx;padding:20rpx 0}.nav text{font-size:50rpx}.nav strong{font-size:32rpx}.card{background:#fff;border-radius:24rpx;padding:24rpx;margin-bottom:20rpx}.head,.foot{display:flex;justify-content:space-between}.head text,.foot text{color:#64748b;font-size:22rpx}.route{display:flex;flex-direction:column;gap:12rpx;padding:22rpx 0}.empty{text-align:center;color:#94a3b8;padding:120rpx}</style>
